from __future__ import annotations

import json
import sys
from pathlib import Path

import pytest
from ds.util.logging import enable_call_logs, log_event, logger

# the app has no package install: import it from its folder
APP_DIR = Path(__file__).resolve().parents[3] / "services" / "ui"
sys.path.insert(0, str(APP_DIR))

from ui import debug_log, logs, session  # noqa: E402
from ui.state import Cell, ChatItem, State  # noqa: E402


@pytest.fixture
def log(tmp_path: Path):
    """The session log written to a temp file for one test: read() gives its records."""
    file = debug_log.RotatingFile(tmp_path / "ui.jsonl")
    sink = logger.add(
        lambda message: file.write(debug_log.line_of(message.record)), filter=lambda r: "kind" in r["extra"]
    )
    debug_log.forget()
    enable_call_logs()  # another test may have turned ds's records off

    def read() -> list[dict]:
        return [json.loads(line) for line in file.path.read_text().splitlines()] if file.path.exists() else []

    yield read
    logger.remove(sink)
    debug_log.forget()
    session._SESSIONS.pop("", None)


def test_a_file_only_record_and_full_detail_stay_out_of_the_panel(log):
    logs.clear()
    log_event("chat", "note", panel=False, text="only the file")
    log_event("agent", "smash-agent", name="turn", prompt="hi", full={"reply": "hello", "traceback": ""})
    panel = logs.records()
    assert [record["kind"] for record in panel] == ["agent"]
    assert "full" not in panel[0]
    assert "reply" not in panel[0]
    note, turn = log()
    assert (note["kind"], note["text"]) == ("chat", "only the file")
    assert (turn["prompt"], turn["reply"]) == ("hi", "hello")
    assert "panel" not in note
    assert "full" not in turn


def test_a_chat_row_is_logged_when_new_or_changed_not_when_redrawn(log):
    asking = ChatItem(kind="assign", key="assign-1", status="asking")
    debug_log.rows_changed("abc12345", [ChatItem(kind="user", key="turn-1", text="hi"), asking], [])
    debug_log.rows_changed("abc12345", [ChatItem(kind="user", key="turn-1", text="hi", open=True), asking], [])
    failed = ChatItem(kind="assign", key="assign-1", status="failed", error="Refused: models, not DataFrames")
    debug_log.rows_changed("abc12345", [ChatItem(kind="user", key="turn-1", text="hi"), failed], [])
    rows = log()
    assert [(row["source"], row.get("status", "")) for row in rows] == [
        ("user", ""),
        ("assign", "asking"),
        ("assign", "failed"),
    ]
    assert rows[-1]["level"] == "ERROR"
    assert all(row["session"] == "abc12345" for row in rows)


def test_the_same_message_twice_is_two_rows(log):
    note = ChatItem(kind="note", text="takes no text after it: not run")
    debug_log.rows_changed("abc12345", [note], [])
    debug_log.rows_changed("abc12345", [note, note], [])
    assert len(log()) == 2


def test_rows_a_session_had_before_a_restart_are_marked_resent(log):
    debug_log.rows_changed("abc12345", [ChatItem(kind="note", text="old")], [])
    debug_log.forget()  # as a backend restart: the chat is kept (.states), what was logged isn't
    debug_log.rows_changed("abc12345", [ChatItem(kind="note", text="old"), ChatItem(kind="note", text="new")], [])
    first, old, new = log()
    assert first["digest"] == old["digest"]
    assert old["resent"]
    assert new["resent"]


def test_a_cell_is_logged_once_it_ran(log):
    debug_log.rows_changed("abc12345", [], [Cell(id="c1", code="1 +")])
    assert log() == []
    debug_log.rows_changed("abc12345", [], [Cell(id="c1", code="x['wins']", count="3", error="KeyError: 'wins'")])
    (cell,) = log()
    assert (cell["kind"], cell["name"], cell["slot"], cell["code"]) == ("cell", "In [3]", "cell:c1", "x['wins']")
    assert cell["level"] == "ERROR"


def test_clearing_the_chat_is_logged(log):
    debug_log.rows_changed("abc12345", [ChatItem(kind="note", text="a"), ChatItem(kind="note", text="b")], [])
    debug_log.rows_changed("abc12345", [], [])
    assert (log()[-1]["source"], log()[-1]["name"]) == ("cleared", "2 rows removed")


def test_the_state_logs_its_chat_rows_when_they_are_sent_to_the_browser(log):
    state = State(_reflex_internal_init=True)  # a flag, not a password
    state.chat.append(ChatItem(kind="note", text="/nope isn't a command"))
    state.get_delta()
    assert [row["text"] for row in log()] == ["/nope isn't a command"]


def test_a_long_value_is_cut(log):
    log_event("chat", "agent", panel=False, text="x" * (debug_log.MAX_VALUE_CHARS + 5))
    assert log()[0]["text"].endswith(f"… ({debug_log.MAX_VALUE_CHARS + 5:,} characters in all)")


def test_the_file_rolls_over_and_keeps_three(tmp_path: Path):
    file = debug_log.RotatingFile(tmp_path / "ui.jsonl", max_bytes=25, keep=3)
    for n in range(8):
        file.write(f"line {n} is ten\n")  # 15 bytes: two don't fit in a file
    names = sorted(path.name for path in tmp_path.iterdir())
    assert names == ["ui.1.jsonl", "ui.2.jsonl", "ui.jsonl"]
    assert file.path.read_text() == "line 7 is ten\n"
    assert file.older(2).read_text() == "line 5 is ten\n"
